-- KYC Evidence Platform - synthetic operational seed (no ground truth in this file)
PRAGMA foreign_keys=ON;
CREATE TABLE customer_type (
  customer_type_id TEXT NOT NULL CHECK (customer_type_id IN ('INDIVIDUAL', 'BUSINESS')),
  description TEXT NOT NULL,
  requires_beneficial_owner INTEGER NOT NULL CHECK (requires_beneficial_owner IN (0, 1)),
  PRIMARY KEY (customer_type_id)
);

CREATE TABLE staff_user (
  user_id TEXT NOT NULL,
  role TEXT NOT NULL CHECK (role IN ('SYSTEM', 'OPERATIONS_ANALYST', 'RISK_COMPLIANCE_REVIEWER', 'SYSTEM_ADMINISTRATOR')),
  display_name TEXT NOT NULL,
  PRIMARY KEY (user_id)
);

CREATE TABLE document_type (
  document_type_code TEXT NOT NULL CHECK (document_type_code IN ('ID_PROOF', 'ADDRESS_PROOF', 'TAX_PROOF', 'SOURCE_OF_FUNDS', 'BUSINESS_REGISTRATION', 'OWNERSHIP_DECLARATION')),
  description TEXT NOT NULL,
  validity_days INTEGER,
  PRIMARY KEY (document_type_code)
);

CREATE TABLE kyc_requirement (
  kyc_requirement_id TEXT NOT NULL,
  customer_type_id TEXT NOT NULL CHECK (customer_type_id IN ('INDIVIDUAL', 'BUSINESS')),
  risk_level TEXT NOT NULL CHECK (risk_level IN ('LOW', 'MEDIUM', 'HIGH')),
  document_type_code TEXT NOT NULL CHECK (document_type_code IN ('ID_PROOF', 'ADDRESS_PROOF', 'TAX_PROOF', 'SOURCE_OF_FUNDS', 'BUSINESS_REGISTRATION', 'OWNERSHIP_DECLARATION')),
  mandatory INTEGER NOT NULL CHECK (mandatory IN (0, 1)),
  policy_version TEXT NOT NULL,
  effective_from TEXT NOT NULL,
  effective_to TEXT,
  PRIMARY KEY (kyc_requirement_id),
  FOREIGN KEY (customer_type_id) REFERENCES customer_type(customer_type_id),
  FOREIGN KEY (document_type_code) REFERENCES document_type(document_type_code),
  UNIQUE (customer_type_id, risk_level, document_type_code, policy_version),
  CHECK (effective_to IS NULL OR effective_to >= effective_from)
);

CREATE TABLE customer (
  customer_id TEXT NOT NULL,
  customer_type_id TEXT NOT NULL CHECK (customer_type_id IN ('INDIVIDUAL', 'BUSINESS')),
  legal_name TEXT NOT NULL,
  country_code TEXT NOT NULL CHECK (country_code IN ('IN', 'US', 'GB', 'SG', 'DE', 'AE', 'BR', 'NG')),
  birth_or_incorporation_date TEXT NOT NULL,
  onboarding_date TEXT NOT NULL,
  risk_level TEXT NOT NULL CHECK (risk_level IN ('LOW', 'MEDIUM', 'HIGH')),
  status TEXT NOT NULL CHECK (status IN ('PENDING', 'APPROVED', 'ON_HOLD')),
  status_since TEXT NOT NULL,
  PRIMARY KEY (customer_id),
  FOREIGN KEY (customer_type_id) REFERENCES customer_type(customer_type_id),
  CHECK (birth_or_incorporation_date < onboarding_date)
);

CREATE TABLE risk_rating (
  risk_rating_id TEXT NOT NULL,
  customer_id TEXT NOT NULL,
  risk_score INTEGER NOT NULL,
  risk_level TEXT NOT NULL CHECK (risk_level IN ('LOW', 'MEDIUM', 'HIGH')),
  score_components TEXT NOT NULL,
  rating_reason TEXT NOT NULL CHECK (rating_reason IN ('INITIAL', 'RE_RATING')),
  effective_from TEXT NOT NULL,
  effective_to TEXT,
  PRIMARY KEY (risk_rating_id),
  FOREIGN KEY (customer_id) REFERENCES customer(customer_id),
  CHECK (effective_to IS NULL OR effective_to > effective_from)
);

CREATE TABLE document (
  document_id TEXT NOT NULL,
  customer_id TEXT NOT NULL,
  document_type_code TEXT NOT NULL CHECK (document_type_code IN ('ID_PROOF', 'ADDRESS_PROOF', 'TAX_PROOF', 'SOURCE_OF_FUNDS', 'BUSINESS_REGISTRATION', 'OWNERSHIP_DECLARATION')),
  name_on_document TEXT NOT NULL,
  document_fingerprint TEXT NOT NULL,
  issue_date TEXT NOT NULL,
  expiry_date TEXT,
  submitted_on TEXT NOT NULL,
  scan_quality_score INTEGER NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('PENDING_VERIFICATION', 'VALID', 'REJECTED', 'EXPIRED', 'SUPERSEDED')),
  supersedes_document_id TEXT,
  PRIMARY KEY (document_id),
  FOREIGN KEY (customer_id) REFERENCES customer(customer_id),
  FOREIGN KEY (document_type_code) REFERENCES document_type(document_type_code),
  FOREIGN KEY (supersedes_document_id) REFERENCES document(document_id),
  CHECK (expiry_date IS NULL OR expiry_date >= issue_date),
  CHECK (submitted_on >= issue_date),
  CHECK (scan_quality_score BETWEEN 0 AND 100)
);

CREATE TABLE verification (
  verification_id TEXT NOT NULL,
  document_id TEXT NOT NULL,
  attempt_no INTEGER NOT NULL,
  verified_on TEXT NOT NULL,
  outcome TEXT NOT NULL CHECK (outcome IN ('VERIFIED', 'REJECTED', 'INCONCLUSIVE')),
  reason_code TEXT NOT NULL CHECK (reason_code IN ('OK', 'NAME_MISMATCH', 'ILLEGIBLE_SCAN', 'EXPIRED_AT_SUBMISSION', 'LOW_CONFIDENCE')),
  verified_by TEXT NOT NULL,
  PRIMARY KEY (verification_id),
  FOREIGN KEY (document_id) REFERENCES document(document_id),
  FOREIGN KEY (verified_by) REFERENCES staff_user(user_id),
  UNIQUE (document_id, attempt_no)
);

CREATE TABLE beneficial_owner (
  owner_id TEXT NOT NULL,
  full_name TEXT NOT NULL,
  date_of_birth TEXT NOT NULL,
  nationality TEXT NOT NULL CHECK (nationality IN ('IN', 'US', 'GB', 'SG', 'DE', 'AE', 'BR', 'NG')),
  PRIMARY KEY (owner_id)
);

CREATE TABLE ownership_link (
  ownership_link_id TEXT NOT NULL,
  customer_id TEXT NOT NULL,
  owner_id TEXT NOT NULL,
  ownership_pct REAL NOT NULL,
  effective_from TEXT NOT NULL,
  effective_to TEXT,
  PRIMARY KEY (ownership_link_id),
  FOREIGN KEY (customer_id) REFERENCES customer(customer_id),
  FOREIGN KEY (owner_id) REFERENCES beneficial_owner(owner_id),
  UNIQUE (customer_id, owner_id, effective_from),
  CHECK (ownership_pct > 0 AND ownership_pct <= 100),
  CHECK (effective_to IS NULL OR effective_to > effective_from)
);

CREATE TABLE customer_decision (
  decision_id TEXT NOT NULL,
  customer_id TEXT NOT NULL,
  decision_date TEXT NOT NULL,
  decision TEXT NOT NULL CHECK (decision IN ('PENDING', 'APPROVED', 'ON_HOLD')),
  required_count INTEGER NOT NULL,
  satisfied_count INTEGER NOT NULL,
  completeness_pct REAL NOT NULL,
  reason_codes TEXT,
  policy_version TEXT NOT NULL,
  decided_by TEXT NOT NULL,
  PRIMARY KEY (decision_id),
  FOREIGN KEY (customer_id) REFERENCES customer(customer_id),
  FOREIGN KEY (decided_by) REFERENCES staff_user(user_id),
  CHECK (satisfied_count <= required_count),
  CHECK (completeness_pct BETWEEN 0 AND 100)
);

CREATE TABLE review_case (
  review_id TEXT NOT NULL,
  customer_id TEXT NOT NULL,
  review_type TEXT NOT NULL CHECK (review_type IN ('PERIODIC')),
  risk_level_at_open TEXT NOT NULL CHECK (risk_level_at_open IN ('LOW', 'MEDIUM', 'HIGH')),
  due_date TEXT NOT NULL,
  opened_on TEXT,
  status TEXT NOT NULL CHECK (status IN ('SCHEDULED', 'OPEN', 'IN_PROGRESS', 'ESCALATED', 'COMPLETED')),
  assigned_to TEXT,
  completed_on TEXT,
  resolution TEXT CHECK (resolution IS NULL OR resolution IN ('NO_CHANGE', 'EVIDENCE_REFRESH_REQUESTED', 'ESCALATED_TO_COMPLIANCE', 'EXIT_RECOMMENDED')),
  PRIMARY KEY (review_id),
  FOREIGN KEY (customer_id) REFERENCES customer(customer_id),
  FOREIGN KEY (assigned_to) REFERENCES staff_user(user_id),
  UNIQUE (customer_id, review_id),
  CHECK (completed_on IS NULL OR opened_on IS NULL OR completed_on >= opened_on)
);

CREATE TABLE review_case_event (
  review_event_id TEXT NOT NULL,
  review_id TEXT NOT NULL,
  from_status TEXT CHECK (from_status IS NULL OR from_status IN ('SCHEDULED', 'OPEN', 'IN_PROGRESS', 'ESCALATED', 'COMPLETED')),
  to_status TEXT NOT NULL CHECK (to_status IN ('SCHEDULED', 'OPEN', 'IN_PROGRESS', 'ESCALATED', 'COMPLETED')),
  event_date TEXT NOT NULL,
  actor_id TEXT NOT NULL,
  note TEXT,
  PRIMARY KEY (review_event_id),
  FOREIGN KEY (review_id) REFERENCES review_case(review_id),
  FOREIGN KEY (actor_id) REFERENCES staff_user(user_id)
);

CREATE TABLE alert (
  alert_id TEXT NOT NULL,
  alert_type TEXT NOT NULL CHECK (alert_type IN ('DOCUMENT_EXPIRING', 'DOCUMENT_EXPIRED', 'REVIEW_OVERDUE')),
  customer_id TEXT NOT NULL,
  document_id TEXT,
  review_id TEXT,
  lead_days INTEGER CHECK (lead_days IS NULL OR lead_days IN (90, 60, 30, 7)),
  severity TEXT NOT NULL CHECK (severity IN ('LOW', 'MEDIUM', 'HIGH')),
  trigger_date TEXT NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('OPEN', 'ACKNOWLEDGED', 'RESOLVED', 'SUPERSEDED')),
  dedupe_key TEXT NOT NULL,
  resolved_on TEXT,
  PRIMARY KEY (alert_id),
  FOREIGN KEY (customer_id) REFERENCES customer(customer_id),
  FOREIGN KEY (document_id) REFERENCES document(document_id),
  FOREIGN KEY (review_id) REFERENCES review_case(review_id)
);

CREATE TABLE alert_event (
  alert_event_id TEXT NOT NULL,
  alert_id TEXT NOT NULL,
  event_type TEXT NOT NULL CHECK (event_type IN ('CREATED', 'ACKNOWLEDGED', 'RESOLVED', 'SUPERSEDED')),
  event_date TEXT NOT NULL,
  actor_id TEXT NOT NULL,
  PRIMARY KEY (alert_event_id),
  FOREIGN KEY (alert_id) REFERENCES alert(alert_id),
  FOREIGN KEY (actor_id) REFERENCES staff_user(user_id)
);

CREATE TABLE audit_event (
  audit_event_id TEXT NOT NULL,
  event_ts TEXT NOT NULL,
  entity_type TEXT NOT NULL,
  entity_id TEXT NOT NULL,
  customer_id TEXT NOT NULL,
  action TEXT NOT NULL,
  actor_type TEXT NOT NULL CHECK (actor_type IN ('CUSTOMER', 'STAFF', 'SYSTEM')),
  actor_id TEXT NOT NULL,
  details TEXT,
  PRIMARY KEY (audit_event_id),
  FOREIGN KEY (customer_id) REFERENCES customer(customer_id)
);

BEGIN TRANSACTION;
PRAGMA defer_foreign_keys=ON;
COMMIT;
